# a naive, risky retry loop
while True:
    try:
        connect()
        break
    except ConnectionError:
        pass   # no delay at all, hammers the server

delay = 1
while not connected:
    try:
        connect()
        connected = True
    except ConnectionError:
        time.sleep(delay)
        delay = min(delay * 2, 60)

for req_id, pending in list(self.pending_requests.items()):
    pending.reject(ConnectionError("Connection lost"))
self.pending_requests.clear()

attempt = 0
while attempt < 5:
    try:
        client.connect()
        client.initialize()
        break
    except ConnectionError:
        attempt += 1
        time.sleep(2 ** attempt)

def reconnect_with_backoff(max_attempts=5, max_delay=30):
    delay = 1
    for attempt in range(max_attempts):
        try:
            return connect()
        except ConnectionError:
            time.sleep(min(delay, max_delay))
            delay *= 2
    raise RuntimeError("Failed to reconnect after maximum attempts")
